"id": "61476219",
"name": "Grilled Onion & Capsicum Salad - includes Guacamole (Regular)",
"category": "Fresh Salads",
"description": "Serves 1 | A delightful celebration of real Mexican flavors, this salad combines fresh greens with corn salsa, creamy guacamole and refreshing pico de gallo. Enriched by protein-packed pinto beans and grilled bell peppers and onions, it offers a perfect balance of zest and freshness. Go ahead and try it out!",
